Given a square matrix mat[][] of order n*n, the task is to check if it is an Idempotent Matrix or not.Idempotent matrix: A matrix is said to be an idempotent matrix if the matrix multiplied by itself returns the same matrix, i.e. the matrix mat[][] is said to be an idempotent matrix if and only if M * M = M.Examples: Input: mat[][] = [[2, -2, -4],                             [-1, 3, 4],                             [1, -2, 3]]Output: TrueExplanation:  Given matrix if multiplied by itself returns the same matrix. Input: mat[][] = [[1, 2],                              [3, 4]]Output: FalseExplanation: Given matrix if multiplied by itself returns the different matrix.Approach:The idea is to multiply matrix mat[][] by itself and check if all the elements of resultant matrix res[][] is equal to corresponding elements of mat[][]. Firstly multiply matrix mat[][] by itself using Matrix Multiplication and store the result in matrix res[][]. Then compare if both the matrices are equal or not.
            C++

    // Program to check given matrix 
// is idempotent matrix or not.
#include<bits/stdc++.h>
using namespace std;

// Function for matrix multiplication.
void mulMatrix(vector<vector<int>>& mat,  
            vector<vector<int>>& res) {
    int n = mat.size();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            for (int k = 0; k < n; k++) {
                res[i][j] += mat[i][k] * mat[k][j];
            }
        }
    }
}

// Function to check idempotent
// property of matrix.
bool checkIdempotent(vector<vector<int>>& mat) {   
    int n = mat.size();

    // multiply matrix mat by iself
    // and store it into res.
    vector<vector<int>> res(n, vector<int>(n, 0));
    mulMatrix(mat, res);

    // check if all the elements of 
    // res are same as mat.
    for (int i = 0; i < n; i++)    
        for (int j = 0; j < n; j++)        
            if (mat[i][j] != res[i][j])
                return false;
    return true;
}

int main() {
    vector<vector<int>> mat = {{2, -2, -4},
                    {-1, 3, 4},
                    {1, -2, -3}};

    if (checkIdempotent(mat))
        cout << "True";
    else
        cout << "False";
    return 0;
}


